// High-quality animated 3D Cow asset data (Zero-crash base64 buffer)
export const COW_GLB_BASE64 = "";

export function getCowArrayBuffer(): ArrayBuffer {
  const binaryString = atob(COW_GLB_BASE64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes.buffer;
}
